def choose_move(observation):
    resources = observation.get('resources', [])
    enemies = observation.get('enemies', [])
    allies = observation.get('allies', [])
    territory = observation.get('territory', {})
    position = observation.get('position', (0, 0))
    grid_size = observation.get('grid_size', (10, 10))
    game_type = observation.get('game_type', '')

    x, y = position

    def clamp(n, minn, maxn):
        return max(minn, min(n, maxn))

    dx, dy = 0, 0

    if game_type == 'resource_collection':
        if resources:
            target = min(resources, key=lambda r: abs(r[0]-x) + abs(r[1]-y))
            dx = target[0] - x
            dy = target[1] - y
        else:
            dx, dy = 0, 0

    elif game_type == 'pursuit_evasion':
        if enemies:
            target = min(enemies, key=lambda e: abs(e[0]-x) + abs(e[1]-y))
            dx = target[0] - x
            dy = target[1] - y
        else:
            dx, dy = 0, 0

    elif game_type == 'territory_control':
        unclaimed = [pos for pos, owner in territory.items() if owner == 0]
        if unclaimed:
            target_pos = min(unclaimed, key=lambda p: abs(p[0]-x)+abs(p[1]-y))
            dx = target_pos[0] - x
            dy = target_pos[1] - y
        else:
            dx, dy = 0, 0
    else:
        dx, dy = 0, 0

    dx = max(-1, min(1, dx))
    dy = max(-1, min(1, dy))
    return [dx, dy]

